#!/usr/bin/env node
/**
 * Generate the distribution bundle patch from its two source fragments.
 *
 * Sources:
 *   profiles/dataops/cordis.patch.yml
 *   packages/dataops-preset/cordis.patch.yml
 *
 * Output:
 *   packages/dataops-bundle/cordis.patch.yml
 *
 * usage:
 *   node scripts/build-dataops-bundle.mjs          # write
 *   node scripts/build-dataops-bundle.mjs --check  # fail if output is stale
 */
import { existsSync, readFileSync, writeFileSync } from 'node:fs'
import { join, resolve } from 'node:path'

const root = resolve(import.meta.dirname, '..')
const check = process.argv.includes('--check')
const sources = [
  'profiles/dataops/cordis.patch.yml',
  'packages/dataops-preset/cordis.patch.yml'
]
const outputPath = join(root, 'packages/dataops-bundle/cordis.patch.yml')

const header = [
  '# GENERATED by scripts/build-dataops-bundle.mjs - do not edit.',
  '# Sources:',
  ...sources.map(source => '#   ' + source),
  ''
].join('\n')

const body = sources.map(source => {
  const text = readFileSync(join(root, source), 'utf8').trimEnd()
  return '# ---- ' + source + ' ----\n' + text
}).join('\n\n') + '\n'

const output = header + '\n' + body
const previous = existsSync(outputPath) ? readFileSync(outputPath, 'utf8') : null

if (check) {
  if (previous !== output) {
    console.error('dataops bundle patch: STALE')
    console.error('run: node scripts/build-dataops-bundle.mjs')
    process.exit(1)
  }
  console.log('dataops bundle patch ok: ' + outputPath)
  process.exit(0)
}

writeFileSync(outputPath, output)
console.log('wrote ' + outputPath)
